create or replace function public.acknowledge_compromiso(p_compromiso_id uuid, p_token character varying, p_ip text DEFAULT NULL::text)
returns jsonb
language plpgsql security definer
set search_path = public, extensions, pg_temp as $$
declare v uuid; v_user text;
begin
  v := public.sesion_validar(p_token::text);
  if v is null then return jsonb_build_object('success',false,'ok',false,'error','unauthorized','message','Not authorized.'); end if;
  select username into v_user from empleados where id = v;
  return public.acknowledge_compromiso(p_empleado_username => v_user, p_compromiso_id => p_compromiso_id, p_ip => p_ip);
end $$;

