  return public.acknowledge_evaluation(p_empleado_username => v_user, p_evaluacion_id => p_evaluacion_id, p_ip => p_ip);
end $$;

do $g$ declare r record; begin
  for r in select p.oid::regprocedure as s from pg_proc p
           where p.pronamespace='public'::regnamespace and p.proname = any(array['admin_cambiar_rol_empleado', 'admin_ciclo_set_fechas', 'admin_eliminar_empleado', 'admin_eliminar_intento_certificacion', 'admin_generar_codigo', 'admin_iniciar_reset_password', 'admin_otorgar_intentos_extra', 'admin_reclasificar_departamento', 'admin_reclasificar_tienda', 'admin_reset_certificacion', 'admin_roster_listar', 'admin_roster_set_ciclo', 'admin_sembrar_certificacion', 'admin_ver_feedback_anonimo', 'evaluacion_config_set', 'evaluacion_progreso', 'evaluacion_resultado', 'cambiar_password', 'certificacion_estado', 'enviar_feedback_anonimo', 'evaluacion_mi_contexto', 'evaluacion_mi_equipo', 'evaluacion_mi_progreso', 'evaluacion_mis_pares', 'feedback_managers_elegibles', 'registro_asignar_tienda', 'evaluacion_elegibilidad_set', 'evaluacion_mis_evaluados', 'metricas_guardar', 'metricas_plantilla_get', 'metricas_plantilla_set', 'evaluacion_kpis_equipo_get', 'evaluacion_kpis_equipo_set', 'acknowledge_compromiso', 'acknowledge_evaluation']) and 'p_token' = any(p.proargnames)
  loop
    execute 'revoke all on function '||r.s||' from public';
    execute 'grant execute on function '||r.s||' to anon, authenticated';
  end loop;
end $g$;
